          "IN00": "（特注制服の裾を整え、背筋を伸ばす。微笑むが、指先が白い）\n\n「……はい。……始め……ますね……っ」",
          "IN01": "（カーテンを閉めて、ベッドの端に腰を下ろす。足が床に届ききらない）\n\n「……ベッド……。……こちら、へ……」",
          "IN02": "「ん……っ……」\n\n（少し背伸びして唇を寄せる。離れたあと、耳まで赤い）\n\n「……はぁ……っ……もう、一回……っ」",
          "IN03": "「んっ……ボタン……、外して……っ」\n\n（肩が出る。視線を逸らしつつ、胸を隠す手が震える）\n\n「……っ……見ないで……。……見て……ください……っ」",
