          "FP05": "（膝をついたまま、上目遣い。唇が触れた瞬間、喉が鳴る）\n\n「ん……んっ……んむっ……」\n\n（離れて息を継ぎ、また咥える。アホ毛が揺れる）\n\n「んっ……はぁ……っ……ん、んっ……」",
          "FP06": "（腿の内側に指が触れただけで、びくりと跳ねる）\n\n「んあっ……！　……見て……ください……っ……もう、こんな……っ」\n\n「入れて……。……お願い……します……っ」",
