          "MN01": "「っ……あ……っ……入っ……た……っ」\n\n（華奢な脚が腰に絡む。一瞬、息が止まる）\n\n「いっ……んっ……動かして……ください……っ」\n\n「っ……あ……っ……生……入っ……た……っ……熱い……っ」",
          "MN02": "「ん……、ん……っ……はぁ……っ」\n\n（ゆっくり出入りするたび、喉の奥で声が溶ける）\n\n「んぅ……っ……奥……あったかい……っ……」",
          "MN03": "「あっ……あっ、ちょ……っ、速い——んあっ！」\n\n（先輩口上が消える。シーツが皺だらけ）\n\n「もっ、と……っ……奥……っ……足りな……い……っ」",
          "MN05": "「あ、っ……また……来る……っ……やだ、止まん……ない……っ」\n\n「んあっ、あっ……言葉……出な……い……っ……うぅっ……！」",
          "MN06": "「やだっ……あ、あ——っっ！」\n\n（数秒、言葉なし。華奢な脚が痙攣するように締まる。アホ毛がぴょこんと揺れる）\n\n「ッ……は、ぁ……っ……今の……ナシ……っ……でも……まだ……っ」",
