          "AF03": "「タオル……っ……手伝って……ください……」\n\n（ベストのボタンがうまくはまらない。耳だけ赤い）\n\n「……汗……、お客さんの、せい……です……っ……牛乳……ほしい……っ」",
          "AF99": "「……ありがとう……ございました……っ……胸……まだ……粘つい……て……っ」",
          "FP08": "（胸で挟む。背伸び。谷間に熱）\n\n「ん……っ……熱い……っ……挟み……ます……っ」\n\n「ん、あっ……上下……っ……んぅっ……！　……出す、時……言って……っ」",
          "FP09": "「んっ……手……っ……握り……ます……っ」\n\n（小さな手が上下。息が細くなる）\n\n「ん、あっ……出して……っ……手、に……っ……粘つい……て……っ」",
          "FP10": "「んっ……擦る……だけ……っ……入れない……っ」\n\n（太ももで挟み、腰が追ってしまう）\n\n「んあっ……っ……熱い……っ……外……出して……ください……っ……太もも……っ」",
