          "MN03": "「あっ……あっ、ちょ……っ、速い——んあっ！」\n\n（先輩口上が消える。シーツが皺だらけ）\n\n「もっ、と……っ……奥……っ……足りな……い……っ」",
          "MN05": "「あ、っ……また……来る……っ……やだ、止まん……ない……っ」\n\n「んあっ、あっ……言葉……出な……い……っ……うぅっ……！」",
          "MN06": "「やだっ……あ、あ——っっ！」\n\n（数秒、言葉なし。華奢な脚が痙攣するように締まる。アホ毛がぴょこんと揺れる）\n\n「ッ……は、ぁ……っ……今の……ナシ……っ……でも……まだ……っ」",
          "AF01:外": "「はぁ……はぁ……っ……離れないで……ください……っ……まだ……余韻……っ……」",
          "AF01:中": "「はぁ……はぁ……っ……重い……です……。……まだ、抜かないで……ください……っ……ちょっと、だけ……」",
          "AF02:外": "「……外……だった、の……っ……次は……中……も……いい……ですか……？」",
          "AF02": "（胸に額を預けたまま、指で制服の裾を掴んでいる）\n\n「……ん……。……また……指名……して……ください……っ」",
          "AF03:外": "「お腹……拭いて……ください……っ……制服……手伝って……」",
          "AF03": "「タオル……っ……手伝って……ください……」\n\n（ベストのボタンがうまくはまらない。耳だけ赤い）\n\n「……汗……、お客さんの、せい……です……っ……牛乳……ほしい……っ」",
          "AF99": "（ドアの前で振り返り、ポニーテールを揺らす。声がまだ少し掠れている）\n\n「……お疲れ……さまでした……っ。……また……いらして……ください……ね……っ」",
          "FIN:act:口": "（口の中で射精する）",
          "FIN:act:顔": "（顔にかけて射精する）",
          "FIN:act:胸": "（胸にかけて射精する）",
          "FIN:口": "「んっ……！ ……ごくん。……ごちそう、さま……です……っ」",
          "FIN:顔": "「んあっ……！ ……顔……あったかい……っ……汚され……ました……っ」",
          "FIN:胸": "「んっ……！ ……谷間……いっぱい……っ……あったかい……っ」",
          "FIN:我慢": "「……ん、んっ……。……まだ……奉仕……続けます……っ」",
          "FIN": "（フィニッシュのタイミング）\n\n「……出す……？　……どこ……っ」",
          "MN07:prompt": "「中……にっ……！　出して……ください……っ……全部……っ」",
          "MN07:中": "「あっ……あったかい……っ……中、いっぱい……んぅっ……ごちそう……さま……っ」",
          "MN07:外": "「あ……外……っ……んあっ……！　……お腹……熱い……っ……う、ぅっ……」",
          "MN07:prompt:生": "「中……にっ……！　出して……ください……っ……全部……っ」",
